import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, KeyboardAvoidingView, Platform, Alert, ScrollView } from 'react-native';
import { useAuth } from '../../hooks/useAuth';
import { useThemeStore } from '../../store';
import Icon from '../../components/Icon';
import {
  handleSocialLogin,
  SOCIAL_PROVIDER_LABELS,
  getAppleBrandColor,
  SocialProvider,
  SocialMessage,
} from './socialAuth';
import { BASE_URL } from '../../api/client';

const CONNECTING_LABEL = 'Connecting...';
const UNCONFIGURED_NOTICE = 'Social login is not configured yet';

interface LoginScreenProps {
  navigation?: any;
  /**
   * Dev/test seam (and the future auth-session hook): supplies a provider
   * idToken directly, skipping the browser step. Mirrors the
   * `idTokenOverride` parameter of handleSocialLogin.
   */
  socialIdTokenOverride?: Partial<Record<SocialProvider, string>>;
}

const LoginScreen = ({ navigation, socialIdTokenOverride }: LoginScreenProps) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [pendingProvider, setPendingProvider] = useState<SocialProvider | null>(null);
  const [socialMessage, setSocialMessage] = useState<SocialMessage | null>(null);
  const { login, isLoading } = useAuth();
  const { theme } = useThemeStore();

  const handleLogin = async () => {
    if (!email || !password) {
      Alert.alert('Error', 'Please fill in all fields');
      return;
    }
    try {
      await login({ email, password });
    } catch (err: any) {
      const message =
        err.response?.data?.message ||
        (err.response ? 'Invalid credentials' : `Unable to connect to backend server at ${BASE_URL}`);
      Alert.alert('Login Failed', message);
    }
  };

  const handleSocialLoginPress = async (provider: SocialProvider, idTokenOverride?: string) => {
    setSocialMessage(null);
    setPendingProvider(provider);
    const result = await handleSocialLogin(provider, idTokenOverride ?? socialIdTokenOverride?.[provider]);
    setPendingProvider(null);
    if (result.status === 'unconfigured') {
      setSocialMessage({ provider, kind: 'notice', text: UNCONFIGURED_NOTICE });
    } else if (result.status === 'error') {
      setSocialMessage({ provider, kind: 'error', text: result.message });
    }
  };

  const socialButtonsDisabled = pendingProvider !== null;

  return (
    <KeyboardAvoidingView
      style={[styles.container, { backgroundColor: theme.colors.background }]}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <ScrollView contentContainerStyle={styles.scroll} keyboardShouldPersistTaps="handled">
        <View style={styles.content}>
          <View style={styles.brandRow}>
            <View style={styles.brandMark}>
              <Icon name="music" size={22} color="#000000" />
            </View>
            <Text style={[styles.logo, { color: theme.colors.text }]}>SpotiBase</Text>
          </View>
          <Text style={[styles.subtitle, { color: theme.colors.textSecondary }]}>
            Millions of songs. Free on SpotiBase.
          </Text>

          <View style={styles.form}>
            <TextInput
              style={[styles.input, { backgroundColor: theme.colors.surface, color: theme.colors.text, borderColor: theme.colors.border }]}
              placeholder="Email or username"
              placeholderTextColor={theme.colors.textTertiary}
              value={email}
              onChangeText={setEmail}
              keyboardType="email-address"
              autoCapitalize="none"
              autoComplete="email"
              accessibilityLabel="Email or username"
            />
            <TextInput
              style={[styles.input, { backgroundColor: theme.colors.surface, color: theme.colors.text, borderColor: theme.colors.border }]}
              placeholder="Password"
              placeholderTextColor={theme.colors.textTertiary}
              value={password}
              onChangeText={setPassword}
              secureTextEntry
              autoComplete="current-password"
              accessibilityLabel="Password"
            />

            <TouchableOpacity
              style={[styles.loginButton, { backgroundColor: theme.colors.primary }]}
              onPress={handleLogin}
              disabled={isLoading}
              accessibilityRole="button"
            >
              <Text style={styles.loginButtonText}>{isLoading ? 'Signing in...' : 'Sign In'}</Text>
            </TouchableOpacity>

            <View style={styles.dividerRow}>
              <View style={[styles.dividerLine, { backgroundColor: theme.colors.border }]} />
              <Text style={[styles.dividerText, { color: theme.colors.textTertiary }]}>or continue with</Text>
              <View style={[styles.dividerLine, { backgroundColor: theme.colors.border }]} />
            </View>

            <TouchableOpacity
              testID="social-button-google"
              style={[styles.socialButton, { borderColor: theme.colors.border }, socialButtonsDisabled && styles.socialButtonDisabled]}
              onPress={() => handleSocialLoginPress('google')}
              disabled={socialButtonsDisabled}
              accessibilityState={{ disabled: socialButtonsDisabled }}
            >
              <Icon name="google" size={18} />
              <Text style={[styles.socialButtonText, { color: theme.colors.text }]}>
                {pendingProvider === 'google' ? CONNECTING_LABEL : SOCIAL_PROVIDER_LABELS.google}
              </Text>
            </TouchableOpacity>
            {socialMessage?.provider === 'google' && (
              <Text style={[styles.socialMessage, { color: socialMessage.kind === 'error' ? theme.colors.error : theme.colors.warning }]}>
                {socialMessage.text}
              </Text>
            )}

            <TouchableOpacity
              testID="social-button-apple"
              style={[styles.socialButton, { borderColor: theme.colors.border }, socialButtonsDisabled && styles.socialButtonDisabled]}
              onPress={() => handleSocialLoginPress('apple')}
              disabled={socialButtonsDisabled}
              accessibilityState={{ disabled: socialButtonsDisabled }}
            >
              <Icon name="apple" size={18} color={getAppleBrandColor(theme.dark)} />
              <Text style={[styles.socialButtonText, { color: getAppleBrandColor(theme.dark) }]}>
                {pendingProvider === 'apple' ? CONNECTING_LABEL : SOCIAL_PROVIDER_LABELS.apple}
              </Text>
            </TouchableOpacity>
            {socialMessage?.provider === 'apple' && (
              <Text style={[styles.socialMessage, { color: socialMessage.kind === 'error' ? theme.colors.error : theme.colors.warning }]}>
                {socialMessage.text}
              </Text>
            )}

            <TouchableOpacity
              style={[styles.signupButton, { borderColor: theme.colors.border }]}
              onPress={() => navigation?.navigate('Register')}
              accessibilityRole="button"
            >
              <Text style={[styles.signupText, { color: theme.colors.text }]}>Sign Up for SpotiBase</Text>
            </TouchableOpacity>
          </View>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1 },
  scroll: { flexGrow: 1, justifyContent: 'center' },
  content: { paddingHorizontal: 28, paddingVertical: 32 },
  brandRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 8,
  },
  brandMark: {
    width: 40,
    height: 40,
    borderRadius: 10,
    backgroundColor: '#1DB954',
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 12,
  },
  logo: { fontSize: 34, fontWeight: '800', letterSpacing: -0.8 },
  subtitle: {
    fontSize: 14,
    textAlign: 'center',
    marginBottom: 32,
    opacity: 0.85,
  },
  form: { gap: 12 },
  input: {
    height: 52,
    borderRadius: 999,
    paddingHorizontal: 20,
    fontSize: 16,
    borderWidth: 1,
  },
  loginButton: {
    height: 52,
    borderRadius: 999,
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: 8,
  },
  loginButtonText: { fontSize: 16, fontWeight: '800', color: '#000000' },
  dividerRow: { flexDirection: 'row', alignItems: 'center', gap: 12, marginVertical: 8 },
  dividerLine: { flex: 1, height: 1 },
  dividerText: { fontSize: 12, fontWeight: '600', textTransform: 'uppercase', letterSpacing: 0.6 },
  socialButton: {
    height: 52,
    borderRadius: 999,
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 1,
    gap: 10,
  },
  socialButtonDisabled: { opacity: 0.5 },
  socialButtonText: { fontSize: 14, fontWeight: '700' },
  socialMessage: { fontSize: 13, textAlign: 'center' },
  signupButton: {
    height: 52,
    borderRadius: 999,
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 1,
    marginTop: 8,
  },
  signupText: { fontSize: 14, fontWeight: '700' },
});

export default LoginScreen;